script = '''import sys, json, sqlite3

# First, let's dump the database schema and data
conn = sqlite3.connect("/workspace/world.db")
conn.row_factory = sqlite3.Row
cur = conn.cursor()

results = {}

# Get all tables
cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
tables = [r[0] for r in cur.fetchall()]
results["tables"] = tables

# For each table, get row count and sample
for t in tables:
    cur.execute(f"SELECT COUNT(*) FROM {t}")
    count = cur.fetchone()[0]
    cur.execute(f"SELECT * FROM {t} LIMIT 3")
    cols = [d[0] for d in cur.description]
    rows = [dict(zip(cols, r)) for r in cur.fetchall()]
    results[t] = {"count": count, "columns": cols, "sample": rows}

# Search for FL398507 across all tables
for t in tables:
    cols_info = results[t]["columns"]
    for col in cols_info:
        try:
            cur.execute(f"SELECT * FROM {t} WHERE {col} LIKE '%398507%'")
            matches = [dict(zip([d[0] for d in cur.description], r)) for r in cur.fetchall()]
            if matches:
                results[f"MATCH_{t}_{col}"] = matches
        except:
            pass

# Search for FL398507 with different formats
for pattern in ['FL398507', 'FL-398507', '398507']:
    for t in tables:
        try:
            for col in results[t]["columns"]:
                cur.execute(f"SELECT * FROM {t} WHERE CAST({col} AS TEXT) LIKE '%{pattern}%'")
                matches = [dict(zip([d[0] for d in cur.description], r)) for r in cur.fetchall()]
                if matches:
                    results[f"FOUND_{pattern}_{t}_{col}"] = matches
        except:
            pass

# Get all flight IDs
for t in tables:
    if 'flight' in t.lower():
        try:
            cur.execute(f"SELECT DISTINCT flight_id FROM {t} LIMIT 20")
            results[f"flight_ids_in_{t}"] = [r[0] for r in cur.fetchall()]
        except:
            try:
                cur.execute(f"SELECT DISTINCT flight_number FROM {t} LIMIT 20")
                results[f"flight_numbers_in_{t}"] = [r[0] for r in cur.fetchall()]
            except:
                pass

# Get all user data
for t in tables:
    if 'user' in t.lower():
        try:
            cur.execute(f"SELECT * FROM {t} LIMIT 10")
            cols = [d[0] for d in cur.description]
            rows = [dict(zip(cols, r)) for r in cur.fetchall()]
            results[f"all_users_{t}"] = rows
        except:
            pass

# Get all reservations/bookings
for t in tables:
    if any(k in t.lower() for k in ['reserv', 'book']):
        try:
            cur.execute(f"SELECT * FROM {t}")
            cols = [d[0] for d in cur.description]
            rows = [dict(zip(cols, r)) for r in cur.fetchall()]
            results[f"all_bookings_{t}"] = rows
        except:
            pass

conn.close()

output = json.dumps(results, indent=2, default=str)
with open("/workspace/db_dump.json", "w") as f:
    f.write(output)
print(output[:3000])
'''
